package com.xyz.question_bank_management_system.modules.agent.tool;
import com.xyz.question_bank_management_system.modules.agent.entity.ResourceItem;import com.xyz.question_bank_management_system.modules.agent.mapper.PersonalizedResourceMapper;import com.xyz.question_bank_management_system.modules.bank.entity.QbQuestion;import com.xyz.question_bank_management_system.modules.bank.mapper.QbQuestionMapper;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;
@Component @RequiredArgsConstructor public class QuestionSimilaritySearchTool {private final PersonalizedResourceMapper resourceMapper;private final QbQuestionMapper questionMapper;public SimilarityResult query(String text,Long bundleId){double max=0;String target="";for(ResourceItem x:resourceMapper.recentQuestions(bundleId,100)){double s=jaccard(text,x.getContentJson());if(s>max){max=s;target=x.getGeneratedQuestionCode();}}for(QbQuestion q:questionMapper.selectRecentPublished(100)){double s=jaccard(text,q.getStem());if(s>max){max=s;target="qb_question:"+q.getId();}}return new SimilarityResult(max,target,max>=0.72);}private double jaccard(String a,String b){Set<String>x=grams(a),y=grams(b);if(x.isEmpty()||y.isEmpty())return 0;Set<String>i=new HashSet<>(x);i.retainAll(y);Set<String>u=new HashSet<>(x);u.addAll(y);return (double)i.size()/u.size();}private Set<String> grams(String s){String n=Objects.toString(s,"").replaceAll("\\s+","").toLowerCase(Locale.ROOT);Set<String>g=new HashSet<>();for(int i=0;i+3<=n.length();i++)g.add(n.substring(i,i+3));return g;}public record SimilarityResult(double score,String matchedTarget,boolean exceedsThreshold) {}}
